import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const board = yield* missions();
  const wanted = board.filter((m) => m.reward >= 100);

  let accepted = 0;

  for (const mission of wanted) {
    const result = yield* acceptMission(mission.id).pipe(Effect.either);

    if (Either.isRight(result)) {
      accepted += 1;
    } else if (result.left._tag === 'NoSlots') {
      break;
    } else {
      return yield* Effect.fail(result.left);
    }
  }

  const completion = yield* completeMissions().pipe(Effect.either);

  if (Either.isLeft(completion)) {
    if (completion.left._tag === 'NothingCompletable') {
      yield* note('Nothing completable.');
    } else {
      return yield* Effect.fail(completion.left);
    }
  }

  return accepted;
});
```

