  const here = yield* orient();
  yield* note(`credits: ${here.credits}`);
});

const goToIf = (id: string) => Effect.gen(function* () {
  const step = yield* goTo(id).pipe(Effect.either);
  if (Either.isRight(step)) return;
  if (step.left._tag === 'InBattle') {
    yield* disengage();
  }
  return yield* Effect.fail(step.left);
});

const mineUntilFull = () => Effect.gen(function* () {
  while (true) {
    const step = yield* mine().pipe(Effect.either);
    if (Either.isRight(step)) continue;

    if (step.left._tag === 'HoldFull') break;

    if (step.left._tag === 'InBattle') {
      yield* disengage();
      continue;
    }

    return yield* Effect.fail(step.left);
  }
});

export default Effect.gen(function* () {
  yield* goToIf('kepler_belt');
  yield* mineUntilFull();
  yield* goToIf('kepler_base');
  yield* sell([{item_id: 'copper_ore'}]);
  yield* service();
  yield* completeMissions().pipe(Effect.catchTag('NothingCompletable', () => Effect.void));
}).pipe(Effect.ensuring(noteCredits()));

