import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

const sellEverything = () => Effect.gen(function* () {
  const here = yield* orient();
  if (here.cargo.length === 0) return;
  yield* sell(here.cargo.map(r => ({item_id: r.item_id})));
});

const salvageAgain = () => salvage().pipe(
  Effect.catchTags({
    NoWreck: () => note('no wreck'),
    InBattle: () => Effect.zipRight(disengage(), salvageAgain()),
    HoldFull: () => Effect.gen(function* () {
      yield* goTo('sol_base');
      yield* sellEverything();
      yield* goTo('sol_debris');
      return yield* salvageAgain();
    }),
  }),
);

export default salvageAgain();

