import {Effect, Either, Schedule, Schema} from 'effect';
import {orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook} from 'play';

// Flight helper: retry only ServerBusy; anything else fails the program (the
// finalizer below still gets to note the credits).
const go = (id: string) =>
  goTo(id).pipe(
    Effect.retry({
      schedule: Schedule.exponential('1 second'),
      times: 3,
      while: (e) => e._tag === 'ServerBusy',
    }),
  );

// Mine one cycle at a time until the hold is full.
// - success: mine again
// - HoldFull: that is the stop we wanted
// - InBattle: pirates engage — disengage, then keep mining
// - anything else: fail with it
const mineUntilFull = () =>
  Effect.gen(function* () {
    while (true) {
      const step = yield* mine().pipe(Effect.either);
      if (Either.isRight(step)) continue;
      const err = step.left;
      if (err._tag === 'HoldFull') break;
      if (err._tag === 'InBattle') {
        yield* disengage();
        continue;
      }
      return yield* Effect.fail(err);
    }
  });

// The last thing the program does, on every path (success or failure).
const noteCredits = () =>
  Effect.gen(function* () {
    const here = yield* orient();
    yield* note(`final: ${here.credits} credits (${here.poi}, hold ${here.cargo_used}/${here.cargo_capacity})`);
  });

export default Effect.gen(function* () {
  // 1 — fly to the copper belt and mine until the hold is full
  const out = yield* go('kepler_belt');
  yield* note(`at ${out.poi}, fuel left ${out.fuel_used === 0 ? 'full' : 'spent ' + out.fuel_used}`);
  yield* mineUntilFull();

  // 2 — bring it home
  const back = yield* go('kepler_base');
  if (back.docked_at === null) yield* note(`warning: not docked at ${back.poi}`);

  // 3 — sell the copper_ore (omit quantity: all of it)
  const sold = yield* sell([{item_id: 'copper_ore'}]);
  yield* note(`sold ${sold.total} credits`);

  // 4 — service the ship
  const rep = yield* service();
  yield* note(`serviced for ${rep.cost} (hull ${rep.hull}, fuel ${rep.fuel})`);

  // 5 — complete what is done; a quiet board is fine
  const done = yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );
  if (done.completed.length > 0) {
    yield* note(`completed ${done.completed.length} mission(s), now at ${done.credits} credits`);
  }

  yield* noteCredits();
}).pipe(Effect.ensuring(noteCredits()));
